# Add debug helper definitions before dbgSpawnGolem.
needle='void dbgSpawnGolem(Sim& s) {'
helpers='''void dbgCompleteLevel(Sim& s) {\n  if (s.phase != PH_PLAY) { setToast(s, T(S_finish_phase)); return; }\n  for (int i = 0; i < MAX_ENEMIES; ++i) if (s.en[i].alive) {\n    const int type = s.en[i].type;\n    s.en[i].alive = false;\n    if (s.enemiesAlive > 0) --s.enemiesAlive;\n    ++s.totalKills;\n    if (s.runKills[type] < 0xFFFF) ++s.runKills[type];\n    s.seenEnemy[type] = true;\n  }\n  for (int i = 0; i < NUM_ENEMIES; ++i) { g.save.enemySeen[i] = true; if (g.save.enemyKills[i] < 0xFFFFFFFFu) ++g.save.enemyKills[i]; }\n  s.wave = s.totalWaves; s.spawned = s.quota; s.bossWave = true; s.bossSpawned = true; s.enemiesAlive = 0;\n  endWave(s);\n  persist();\n  setToast(s, "LEVEL COMPLETE / BESTIARY UNLOCKED");\n}\nvoid dbgAddMinute(Sim& s) {\n  if (s.phase == PH_DEAD || s.phase == PH_VICTORY) { setToast(s, T(S_finish_phase)); return; }\n  s.runT += 60.0f;\n  addLifetime(g.save.playTimeSeconds, 60);\n  persist();\n  setToast(s, "+1 MINUTE");\n}\n'''
